    // Helper function to load images
    const loadImage = (src) =>
      new Promise((resolve) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.onload = () => resolve(img);
        img.src = src;
      });

    // Function to get color swatches from an image
    const getColorSwatches = async (imageUrl) => {
      return new Promise((resolve) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.onload = () => {
          const tempCanvas = document.createElement('canvas');
          const tempCtx = tempCanvas.getContext('2d');
          tempCanvas.width = 100;
          tempCanvas.height = 100;
          tempCtx.drawImage(img, 0, 0, 100, 100);

          const imageData = tempCtx.getImageData(0, 0, 100, 100);
          const pixels = imageData.data;
          const colors = new Set();

          for (let i = 0; i < pixels.length; i += 4) {
            if (pixels[i + 3] > 128) {
              const color = `rgb(${pixels[i]},${pixels[i + 1]},${pixels[i + 2]})`;
              colors.add(color);
            }
          }

          resolve(Array.from(colors));
        };
        img.src = imageUrl;
      });
    };

    // Function to draw color shapes with complete coverage
    const drawColorShapes = (colors) => {
      const gridSize = 50; // Size of each grid cell
      const cols = Math.ceil(width / gridSize);
      const rows = Math.ceil(height / gridSize);

      // Create a grid of positions
      const positions = [];
      for (let y = 0; y < rows; y++) {
        for (let x = 0; x < cols; x++) {
          positions.push({ x: x * gridSize, y: y * gridSize });
        }
      }

      // Shuffle positions
      for (let i = positions.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [positions[i], positions[j]] = [positions[j], positions[i]];
      }

      // Draw shapes to fill the grid
      positions.forEach(pos => {
        const color = colors[Math.floor(Math.random() * colors.length)];
        const size = gridSize * (1 + Math.random() * 0.5); // Random size between gridSize and 1.5*gridSize

        ctx.fillStyle = color;

        // Randomly choose between circle and rectangle
        if (Math.random() > 0.5) {
          ctx.beginPath();
          ctx.arc(pos.x + gridSize/2, pos.y + gridSize/2, size/2, 0, Math.PI * 2);
          ctx.fill();
        } else {
          ctx.fillRect(pos.x, pos.y, size, size);
        }
      });
    };

    // Function to create and overlay image pieces
    const overlayImagePieces = (img) => {
      const numPieces = 50;
      const pieces = [];

      // Create a grid of positions
      const gridSize = Math.sqrt((width * height) / numPieces);
      const cols = Math.ceil(width / gridSize);
      const rows = Math.ceil(height / gridSize);

      // Generate pieces
      for (let i = 0; i < numPieces; i++) {
        const size = gridSize * (0.8 + Math.random() * 0.4); // Random size between 0.8 and 1.2 times gridSize
        const x = Math.random() * (width - size);
        const y = Math.random() * (height - size);

        pieces.push({
          x,
          y,
          width: size,
          height: size
        });
      }

      // Draw pieces
      pieces.forEach(piece => {
        ctx.save();
        ctx.beginPath();
        ctx.rect(piece.x, piece.y, piece.width, piece.height);
        ctx.clip();
        ctx.drawImage(img, 0, 0, width, height);
        ctx.restore();
      });
    };

    // Main generation process
    Promise.all(imagePaths.map(loadImage)).then(async (images) => {
      // Create a temporary canvas for the color layer
      const colorCanvas = document.createElement('canvas');
      colorCanvas.width = width;
      colorCanvas.height = height;
      const colorCtx = colorCanvas.getContext('2d');

      // Get all color swatches from selected images
      const allColors = [];
      for (const img of images) {
        const colors = await getColorSwatches(img.src);
        allColors.push(...colors);
      }

      // Draw color shapes on the temporary canvas
      drawColorShapes(allColors);

      // Draw the color layer on the main canvas
      ctx.drawImage(colorCanvas, 0, 0);

      // Set up multiplication blend mode
      ctx.globalCompositeOperation = 'multiply';

      // Overlay image pieces
      for (const img of images) {
        overlayImagePieces(img);
      }

      // Reset blend mode
      ctx.globalCompositeOperation = 'source-over';

      // Apply effects
      if (effects.grain) generateGrain(ctx, width, height);
      if (effects.scanlines) applyScanlines(ctx, width, height);
      if (effects.aberration) applyChromaticAberration(ctx, width, height);
      if (effects.glitch) applyGlitchEffect(ctx, width, height);
    });
  };

  const handleDownload = () => {
    const canvas = canvasRef.current;
    const link = document.createElement("a");
    link.download = "generated.png";
    link.href = canvas.toDataURL("image/png");
    link.click();
  };

  const handleRegenerate = () => {
    setIsFading(true);
    setTimeout(() => {
      generateImage(imagePaths);
      setIsFading(false);
    }, 300);
  };

  return (
    <div
      ref={containerRef}
      style={{
        width: "100vw",
        height: "100vh",
        overflow: "hidden",
        position: "relative",
        touchAction: "none",
        cursor: isDragging.current ? "grabbing" : "grab",
        background: "#000",
      }}
    >
      <div style={{
  position: "absolute",
  top: 20,
  left: 20,
  background: "rgba(255,255,255,0.9)",
  padding: "10px 15px",
  borderRadius: "10px",
  zIndex: 10
}}>
  <label>
    <input
      type="checkbox"
      checked={effects.grain}
      onChange={() => setEffects(prev => ({ ...prev, grain: !prev.grain }))}
    /> Grain
  </label>
  <br />
  <label>
    <input
      type="checkbox"
      checked={effects.scanlines}
      onChange={() => setEffects(prev => ({ ...prev, scanlines: !prev.scanlines }))}
    /> Scanlines
  </label>
  <br />
  <label>
    <input
      type="checkbox"
      checked={effects.aberration}
      onChange={() => setEffects(prev => ({ ...prev, aberration: !prev.aberration }))}
    /> Chromatic Aberration
  </label>
  <br />
  <label>
    <input
      type="checkbox"
      checked={effects.glitch}
      onChange={() => setEffects(prev => ({ ...prev, glitch: !prev.glitch }))}
    /> Glitch
  </label>
</div>


      <canvas
        ref={canvasRef}
        width={1080}
        height={1080}
        style={{
          display: "block",
          margin: "0 auto",
          opacity: isFading ? 0.2 : 1,
          transition: "opacity 0.3s ease",
        }}
      />
<div style={{ position: "fixed", top: 20, right: 20, display: "flex", gap: "12px", zIndex: 10 }}>
  <button
    onClick={handleRegenerate}
    style={{
      padding: "8px 16px",
      backgroundColor: "#FFD666",
      border: "none",
      borderRadius: "8px",
      cursor: "pointer",
      fontWeight: "bold",
    }}
  >
    Regenerate
  </button>
  <button
    onClick={handleDownload}
    style={{
      padding: "8px 16px",
      backgroundColor: "#333",
      color: "#fff",
      border: "none",
      borderRadius: "8px",
      cursor: "pointer",
      fontWeight: "bold",
    }}
  >
    Download
  </button>
</div>
    </div>
  );
}

export default Generate;
